 * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or
 * implied.  See the License for the specific language governing
 * permissions and limitations under the License.
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <debug.h>
#include <errno.h>

#include "smart_lock_config.h"
#include "radar_driver.h"
#include "door_sensor.h"
#include "door_control.h"
#include "safety.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define TAG "smart_lock"

/****************************************************************************
 * Private Types
 ****************************************************************************/

/* System state machine */

enum smart_lock_state_e
{
  STATE_IDLE = 0,             /* Door closed, waiting for radar trigger */
  STATE_DOOR_OPEN,            /* Door open, countdown active */
  STATE_CLOSING,              /* Motor closing door */
  STATE_CLOSED_UNCONFIRMED,   /* Door closing, waiting for confirmation */
  STATE_LOCKED,               /* Door closed and locked */
  STATE_ANTI_PINCH,           /* Anti-pinch detected, reversing */
  STATE_ERROR                 /* Error state */
};

/* Application context */

struct smart_lock_ctx_s
{
  volatile enum smart_lock_state_e state;
  volatile bool running;

  /* Door open timeout */

  uint32_t door_open_timeout_ms;
  uint32_t door_open_start_ms;

  /* Radar presence tracking */

  volatile bool person_detected;
  volatile uint8_t zone_status;

  /* Thread IDs */

  pthread_t main_task_tid;
  pthread_t radar_task_tid;
  pthread_t ui_task_tid;

  /* Synchronization */

  pthread_mutex_t state_mutex;
  pthread_cond_t  state_cond;
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct smart_lock_ctx_s g_ctx;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: get_timestamp_ms
 *
 * Description:
 *   Get current timestamp in milliseconds.
 *
 ****************************************************************************/

static uint32_t get_timestamp_ms(void)
{
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (uint32_t)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);
}

/****************************************************************************
 * Name: set_state
 *
 * Description:
 *   Thread-safe state transition.
 *
 ****************************************************************************/

static void set_state(enum smart_lock_state_e new_state)
{
  pthread_mutex_lock(&g_ctx.state_mutex);
  syslog(LOG_INFO, TAG": State %d -> %d\n", g_ctx.state, new_state);
  g_ctx.state = new_state;
  pthread_cond_broadcast(&g_ctx.state_cond);
  pthread_mutex_unlock(&g_ctx.state_mutex);
}

/****************************************************************************
 * Name: radar_callback
 *
 * Description:
 *   Called by radar driver when new detection data is available.
 *
 ****************************************************************************/

static void radar_callback(FAR const struct radar_result_s *result,
                           FAR void *arg)
{
  if (result == NULL)
    {
      return;
    }

  g_ctx.person_detected = (result->state != RADAR_STATE_NO_TARGET);
  g_ctx.zone_status = result->zone;

  syslog(LOG_DEBUG, TAG": Radar: state=%d zone=%d dist=%dcm\n",
         result->state, result->zone, result->distance_cm);
}

/****************************************************************************
 * Name: door_event_callback
 *
 * Description:
 *   Called by door sensor when door state changes.
 *
 ****************************************************************************/

static void door_event_callback(FAR const struct door_status_s *status,
                                FAR void *arg)
{
  if (status == NULL)
    {
      return;
    }

  if (status->last_event == DOOR_EVENT_OPENED)
    {
      syslog(LOG_INFO, TAG": Door opened\n");
      g_ctx.door_open_start_ms = get_timestamp_ms();

      if (g_ctx.state == STATE_IDLE ||
          g_ctx.state == STATE_LOCKED)
        {
          set_state(STATE_DOOR_OPEN);
        }
    }
  else if (status->last_event == DOOR_EVENT_CLOSED)
    {
      syslog(LOG_INFO, TAG": Door closed\n");
    }
}

/****************************************************************************
 * Name: safety_callback
 *
 * Description:
 *   Called by safety system when an alert is triggered.
 *
 ****************************************************************************/

static void safety_callback(FAR const struct safety_alert_s *alert,
                            FAR void *arg)
{
  if (alert == NULL)
    {
      return;
    }

  syslog(LOG_WARNING, TAG": Safety alert: type=%d severity=%d msg=%s\n",
         alert->type, alert->severity, alert->message);

  if (alert->type == SAFETY_ALERT_ANTI_PINCH)
    {
      /* Emergency stop and reverse */

      door_control_stop();
      set_state(STATE_ANTI_PINCH);
    }
}

/****************************************************************************
 * Name: handle_idle_state
 *
 * Description:
 *   Handle the IDLE state - door is closed, waiting for radar trigger.
 *
 ****************************************************************************/

static void handle_idle_state(void)
{
  /* In idle state, we just wait for door sensor to detect opening */

  pthread_mutex_lock(&g_ctx.state_mutex);
  while (g_ctx.state == STATE_IDLE && g_ctx.running)
    {
      struct timespec ts;
      clock_gettime(CLOCK_MONOTONIC, &ts);
      ts.tv_sec += 1;
      pthread_cond_timedwait(&g_ctx.state_cond, &g_ctx.state_mutex, &ts);
    }

  pthread_mutex_unlock(&g_ctx.state_mutex);
}

/****************************************************************************
 * Name: handle_door_open_state
 *
 * Description:
 *   Handle the DOOR_OPEN state - countdown to auto-close.
 *
 ****************************************************************************/

static void handle_door_open_state(void)
{
  uint32_t elapsed;

  while (g_ctx.state == STATE_DOOR_OPEN && g_ctx.running)
    {
      elapsed = get_timestamp_ms() - g_ctx.door_open_start_ms;

      /* If person detected, reset timeout */

      if (g_ctx.person_detected)
        {
          g_ctx.door_open_start_ms = get_timestamp_ms();
          syslog(LOG_DEBUG, TAG": Person detected, timeout reset\n");
        }

      /* Check if timeout reached */

      if (elapsed >= g_ctx.door_open_timeout_ms)
        {
          syslog(LOG_INFO, TAG": Timeout reached, starting close\n");

          /* Start anti-pinch monitoring before closing */

          safety_start_monitoring();

          /* Execute close command */

          if (door_control_execute(MOTOR_CMD_CLOSE) == 0)
            {
              set_state(STATE_CLOSING);
            }
          else
            {
              syslog(LOG_ERR, TAG": Failed to start motor\n");
              safety_stop_monitoring();
              set_state(STATE_ERROR);
            }

          return;
        }

      /* Sleep for a short interval */

      usleep(100000);  /* 100ms */
    }
}

/****************************************************************************
 * Name: handle_closing_state
 *
 * Description:
 *   Handle the CLOSING state - motor is running, waiting for completion.
 *
 ****************************************************************************/

static void handle_closing_state(void)
{
  struct motor_status_s motor_status;
  uint32_t start_time = get_timestamp_ms();

  while (g_ctx.state == STATE_CLOSING && g_ctx.running)
    {
      door_control_get_status(&motor_status);

      /* Check if motor finished */

      if (motor_status.state == MOTOR_STATE_IDLE)
        {
          safety_stop_monitoring();

          /* Check if door is actually closed */

          if (door_sensor_is_closed())
            {
              syslog(LOG_INFO, TAG": Door closed, locking\n");
              door_control_execute(MOTOR_CMD_LOCK);
              set_state(STATE_LOCKED);
            }
          else
            {
              syslog(LOG_WARNING, TAG": Motor done but door not closed\n");
              set_state(STATE_ERROR);
            }

          return;
        }

      /* Check for timeout */

      if (get_timestamp_ms() - start_time > SAFETY_TIMEOUT_MS)
        {
          syslog(LOG_ERR, TAG": Motor timeout\n");
          door_control_stop();
          safety_stop_monitoring();
          set_state(STATE_ERROR);
          return;
        }

      usleep(50000);  /* 50ms */
    }
}

/****************************************************************************
 * Name: handle_anti_pinch_state
 *
 * Description:
 *   Handle the ANTI_PINCH state - reverse motor and alert.
 *
 ****************************************************************************/

static void handle_anti_pinch_state(void)
{
  syslog(LOG_WARNING, TAG": Anti-pinch! Reversing motor\n");

  /* Trigger alarm */

  safety_trigger_alarm(SAFETY_ALERT_ANTI_PINCH);

  /* Open door to release */

  door_control_execute(MOTOR_CMD_OPEN);
  usleep(DOOR_CLOSE_DURATION_MS * 1000);
  door_control_stop();

  /* Wait for person to clear */

  sleep(2);

  /* Stop alarm */

  safety_stop_alarm();

  /* Go back to door open state */

  g_ctx.door_open_start_ms = get_timestamp_ms();
  set_state(STATE_DOOR_OPEN);
}

/****************************************************************************
 * Name: handle_error_state
 *
 * Description:
 *   Handle the ERROR state - wait and try to recover.
 *
 ****************************************************************************/

static void handle_error_state(void)
{
  syslog(LOG_ERR, TAG": In error state, attempting recovery\n");

  /* Stop everything */

  door_control_stop();
  safety_stop_monitoring();
  safety_stop_alarm();

  /* Wait a bit */

  sleep(3);

  /* Check current state */

  if (door_sensor_is_closed())
    {
      set_state(STATE_LOCKED);
    }
  else
    {
      g_ctx.door_open_start_ms = get_timestamp_ms();
      set_state(STATE_DOOR_OPEN);
    }
}

/****************************************************************************
 * Name: smart_lock_main_task
 *
 * Description:
 *   Main task - state machine loop.
 *
 ****************************************************************************/

static FAR void *smart_lock_main_task(FAR void *arg)
{
  syslog(LOG_INFO, TAG": Main task started\n");

  while (g_ctx.running)
    {
      switch (g_ctx.state)
        {
          case STATE_IDLE:
            handle_idle_state();
            break;

          case STATE_DOOR_OPEN:
            handle_door_open_state();
            break;

          case STATE_CLOSING:
            handle_closing_state();
            break;

          case STATE_ANTI_PINCH:
            handle_anti_pinch_state();
            break;

          case STATE_LOCKED:
            /* Wait for door to be opened */

            pthread_mutex_lock(&g_ctx.state_mutex);
            while (g_ctx.state == STATE_LOCKED && g_ctx.running)
              {
                struct timespec ts;
                clock_gettime(CLOCK_MONOTONIC, &ts);
                ts.tv_sec += 1;
                pthread_cond_timedwait(&g_ctx.state_cond,
                                       &g_ctx.state_mutex, &ts);
              }

            pthread_mutex_unlock(&g_ctx.state_mutex);
            break;

          case STATE_ERROR:
            handle_error_state();
            break;

          default:
            syslog(LOG_ERR, TAG": Unknown state: %d\n", g_ctx.state);
            set_state(STATE_ERROR);
            break;
        }
    }

  syslog(LOG_INFO, TAG": Main task exiting\n");
  return NULL;
}

/****************************************************************************
 * Name: init_subsystems
 *
 * Description:
 *   Initialize all hardware subsystems.
 *
 ****************************************************************************/

static int init_subsystems(void)
{
  int ret;

  /* Initialize door control (motor GPIO/PWM) */

  ret = door_control_init();
  if (ret < 0)
    {
      syslog(LOG_ERR, TAG": door_control_init failed: %d\n", ret);
      return ret;
    }

  /* Initialize door sensor (magnetic reed switch) */

  ret = door_sensor_init();
  if (ret < 0)
    {
      syslog(LOG_ERR, TAG": door_sensor_init failed: %d\n", ret);
      goto err_door_ctrl;
    }

  /* Register door event callback */

  door_sensor_register_callback(door_event_callback, NULL);

  /* Initialize safety system (anti-pinch) */

  ret = safety_init();
  if (ret < 0)
    {
      syslog(LOG_ERR, TAG": safety_init failed: %d\n", ret);
      goto err_door_sensor;
    }

  /* Register safety callback */

  safety_register_callback(safety_callback, NULL);

  /* Initialize radar driver */

  ret = radar_driver_init();
  if (ret < 0)
    {
      syslog(LOG_ERR, TAG": radar_driver_init failed: %d\n", ret);
      goto err_safety;
    }

  /* Register radar callback */

  radar_register_callback(radar_callback, NULL);

  syslog(LOG_INFO, TAG": All subsystems initialized\n");
  return 0;

err_safety:
  safety_deinit();
err_door_sensor:
  door_sensor_deinit();
err_door_ctrl:
  door_control_deinit();
  return ret;
}

/****************************************************************************
 * Name: deinit_subsystems
 *
 * Description:
 *   Deinitialize all hardware subsystems.
 *
 ****************************************************************************/

static void deinit_subsystems(void)
{
  radar_driver_deinit();
  safety_deinit();
  door_sensor_deinit();
  door_control_deinit();
  syslog(LOG_INFO, TAG": All subsystems deinitialized\n");
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: smart_lock_main
 *
 * Description:
 *   Application entry point for the Smart Lock Guardian system.
 *
 * Input Parameters:
 *   argc - Number of arguments
 *   argv - Argument array
 *
 * Returned Value:
 *   0 on success, non-zero on failure.
 *
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  int ret;
  pthread_attr_t attr;

  syslog(LOG_INFO, TAG": Smart Lock Guardian v1.0 starting\n");

  /* Initialize context */

  memset(&g_ctx, 0, sizeof(g_ctx));
  g_ctx.state = STATE_IDLE;
  g_ctx.running = true;
  g_ctx.door_open_timeout_ms = DOOR_OPEN_TIMEOUT_MS;

  pthread_mutex_init(&g_ctx.state_mutex, NULL);
  pthread_cond_init(&g_ctx.state_cond, NULL);

  /* Initialize all subsystems */

  ret = init_subsystems();
  if (ret < 0)
    {
      syslog(LOG_ERR, TAG": Subsystem init failed: %d\n", ret);
      return EXIT_FAILURE;
    }

  /* Create main task */

  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, STACK_DOOR_CTRL);
  pthread_attr_setschedpolicy(&attr, SCHED_RR);

  ret = pthread_create(&g_ctx.main_task_tid, &attr,
                       smart_lock_main_task, NULL);
  if (ret != 0)
    {
      syslog(LOG_ERR, TAG": Failed to create main task: %d\n", ret);
      goto err_deinit;
    }

  syslog(LOG_INFO, TAG": Smart Lock Guardian running\n");

  /* Wait for main task to complete (shouldn't unless error) */

  pthread_join(g_ctx.main_task_tid, NULL);

  /* Cleanup */

  deinit_subsystems();
  pthread_mutex_destroy(&g_ctx.state_mutex);
  pthread_cond_destroy(&g_ctx.state_cond);

  syslog(LOG_INFO, TAG": Smart Lock Guardian exited\n");
  return EXIT_SUCCESS;

err_deinit:
  deinit_subsystems();
  pthread_mutex_destroy(&g_ctx.state_mutex);
  pthread_cond_destroy(&g_ctx.state_cond);
  return EXIT_FAILURE;
}

