/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define TAG "radar"
#define RADAR_BUF_SIZE  64
#define RADAR_TASK_STACK 4096

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct radar_dev_s
{
  int fd;                         /* UART file descriptor */
  volatile bool running;          /* Task running flag */
  pthread_t task_tid;             /* Receive task thread ID */
  radar_callback_t callback;      /* Detection callback */
  FAR void *callback_arg;         /* Callback argument */
  struct radar_result_s latest;   /* Latest detection result */
  pthread_mutex_t lock;           /* Data protection mutex */
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct radar_dev_s g_radar;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: radar_parse_frame
 *
 * Description:
 *   Parse a radar data frame. The 24GHz radar module sends data in
 *   a specific format with header byte 0xAA followed by data bytes.
 *
 *   Frame format:
 *   [0xAA] [Len] [Type] [Data...] [Checksum]
 *
 ****************************************************************************/

static int radar_parse_frame(FAR const uint8_t *frame, size_t len,
                             FAR struct radar_result_s *result)
{
  uint8_t checksum;
  size_t i;

  if (frame == NULL || result == NULL || len < 4)
    {
      return -EINVAL;
    }

  /* Verify header */

  if (frame[0] != RADAR_FRAME_HEADER)
    {
      return -EPROTO;
    }

  /* Verify checksum (XOR of all bytes except header and checksum) */

  checksum = 0;
  for (i = 1; i < len - 1; i++)
    {
      checksum ^= frame[i];
    }

  if (checksum != frame[len - 1])
    {
      syslog(LOG_WARNING, TAG": Checksum error: calc=%02x recv=%02x\n",
             checksum, frame[len - 1]);
      return -EIO;
    }

  /* Parse data based on type */

  result->timestamp = (uint32_t)time(NULL);

  switch (frame[2])
    {
      case 0x01:  /* Presence detection */
        result->state = frame[3] ? RADAR_STATE_MOVING :
                                   RADAR_STATE_NO_TARGET;
        result->zone = frame[4];
        result->distance_cm = (uint16_t)(frame[5] << 8 | frame[6]);
        result->energy = (uint16_t)(frame[7] << 8 | frame[8]);
        break;

      case 0x02:  /* Motion detection */
        if (frame[3] > 0)
          {
            result->state = frame[3] < 128 ?
                            RADAR_STATE_STATIONARY :
                            RADAR_STATE_MOVING;
          }
        else
          {
            result->state = RADAR_STATE_NO_TARGET;
          }

        result->zone = frame[4];
        result->distance_cm = (uint16_t)(frame[5] << 8 | frame[6]);
        result->energy = (uint16_t)(frame[7] << 8 | frame[8]);
        break;

      case 0x03:  /* Zone detection */
        result->zone = frame[3];
        result->state = result->zone ? RADAR_STATE_MOVING :
                                       RADAR_STATE_NO_TARGET;
        result->distance_cm = 0;
        result->energy = 0;
        break;

      default:
        syslog(LOG_WARNING, TAG": Unknown frame type: %02x\n", frame[2]);
        return -ENOTSUP;
    }

  /* Determine event type based on state change */

  if (result->state != RADAR_STATE_NO_TARGET &&
      g_radar.latest.state == RADAR_STATE_NO_TARGET)
    {
      result->event = RADAR_EVENT_ENTER;
    }
  else if (result->state == RADAR_STATE_NO_TARGET &&
           g_radar.latest.state != RADAR_STATE_NO_TARGET)
    {
      result->event = RADAR_EVENT_LEAVE;
    }
  else
    {
      result->event = RADAR_EVENT_STAY;
    }

  return 0;
}

/****************************************************************************
 * Name: radar_configure_uart
 *
 * Description:
 *   Configure the UART port for radar communication.
 *
 ****************************************************************************/

static int radar_configure_uart(int fd)
{
  struct termios tio;
  int ret;

  ret = tcgetattr(fd, &tio);
  if (ret < 0)
    {
      syslog(LOG_ERR, TAG": tcgetattr failed: %d\n", errno);
      return -errno;
    }

  /* Set baud rate */

  cfsetispeed(&tio, RADAR_UART_BAUD);
  cfsetospeed(&tio, RADAR_UART_BAUD);

  /* 8N1, no parity, enable receiver */

  tio.c_cflag = CS8 | CREAD | CLOCAL;
  tio.c_iflag = 0;
  tio.c_oflag = 0;
  tio.c_lflag = 0;

  /* Non-blocking read with timeout */

  tio.c_cc[VMIN] = 0;
  tio.c_cc[VTIME] = 1;  /* 100ms timeout */

  ret = tcsetattr(fd, TCSANOW, &tio);
  if (ret < 0)
    {
      syslog(LOG_ERR, TAG": tcsetattr failed: %d\n", errno);
      return -errno;
    }

  return 0;
}

/****************************************************************************
 * Name: radar_receive_task
 *
 * Description:
 *   Background task that reads radar data from UART and parses frames.
 *
 ****************************************************************************/

static FAR void *radar_receive_task(FAR void *arg)
{
  uint8_t buf[RADAR_BUF_SIZE];
  uint8_t frame[RADAR_FRAME_LEN];
  size_t frame_pos = 0;
  bool in_frame = false;
  ssize_t nread;
  struct radar_result_s result;
  int ret;

  syslog(LOG_INFO, TAG": Receive task started\n");

  while (g_radar.running)
    {
      /* Read data from UART */

      nread = read(g_radar.fd, buf, sizeof(buf));
      if (nread <= 0)
        {
          if (nread < 0 && errno != EAGAIN && errno != ETIMEDOUT)
            {
              syslog(LOG_ERR, TAG": Read error: %d\n", errno);
            }

          usleep(10000);  /* 10ms */
          continue;
        }

      /* Process each byte */

      for (ssize_t i = 0; i < nread; i++)
        {
          if (!in_frame)
            {
              /* Looking for frame header */

              if (buf[i] == RADAR_FRAME_HEADER)
                {
                  frame[0] = buf[i];
                  frame_pos = 1;
                  in_frame = true;
                }
            }
          else
            {
              /* Accumulating frame data */

              frame[frame_pos++] = buf[i];

              /* Check if we have a complete frame */

              if (frame_pos >= 2 && frame_pos >= frame[1] + 2)
                {
                  /* Parse the frame */

                  ret = radar_parse_frame(frame, frame_pos, &result);
                  if (ret == 0)
                    {
                      /* Update latest result */

                      pthread_mutex_lock(&g_radar.lock);
                      g_radar.latest = result;
                      pthread_mutex_unlock(&g_radar.lock);

                      /* Notify callback */

                      if (g_radar.callback != NULL)
                        {
                          g_radar.callback(&result,
                                          g_radar.callback_arg);
                        }
                    }

                  in_frame = false;
                  frame_pos = 0;
                }

              /* Prevent buffer overflow */

              if (frame_pos >= RADAR_FRAME_LEN)
                {
                  in_frame = false;
                  frame_pos = 0;
                }
            }
        }
    }

  syslog(LOG_INFO, TAG": Receive task exiting\n");
  return NULL;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int radar_driver_init(void)
{
  pthread_attr_t attr;
  int ret;

  syslog(LOG_INFO, TAG": Initializing radar driver\n");

  /* Initialize context */

  memset(&g_radar, 0, sizeof(g_radar));
  g_radar.fd = -1;
  g_radar.running = false;
  pthread_mutex_init(&g_radar.lock, NULL);

  /* Open UART port */

  g_radar.fd = open(RADAR_UART_PORT, O_RDONLY | O_NOCTTY);
  if (g_radar.fd < 0)
    {
      syslog(LOG_ERR, TAG": Failed to open %s: %d\n",
             RADAR_UART_PORT, errno);
      return -errno;
    }

  /* Configure UART */

  ret = radar_configure_uart(g_radar.fd);
  if (ret < 0)
    {
      syslog(LOG_ERR, TAG": UART config failed: %d\n", ret);
      goto err_close;
    }

  /* Start receive task */

  g_radar.running = true;

  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, RADAR_TASK_STACK);
  pthread_attr_setschedpolicy(&attr, SCHED_RR);

  ret = pthread_create(&g_radar.task_tid, &attr,
                       radar_receive_task, NULL);
  if (ret != 0)
    {
      syslog(LOG_ERR, TAG": Failed to create task: %d\n", ret);
      g_radar.running = false;
      goto err_close;
    }

  syslog(LOG_INFO, TAG": Radar driver initialized on %s\n",
         RADAR_UART_PORT);
  return 0;

err_close:
  close(g_radar.fd);
  g_radar.fd = -1;
  pthread_mutex_destroy(&g_radar.lock);
  return ret;
}

void radar_driver_deinit(void)
{
  syslog(LOG_INFO, TAG": Deinitializing radar driver\n");

  /* Stop receive task */

  g_radar.running = false;
  if (g_radar.task_tid != 0)
    {
      pthread_join(g_radar.task_tid, NULL);
    }

  /* Close UART */

  if (g_radar.fd >= 0)
    {
      close(g_radar.fd);
      g_radar.fd = -1;
    }

  pthread_mutex_destroy(&g_radar.lock);
}

void radar_register_callback(radar_callback_t callback, FAR void *arg)
{
  pthread_mutex_lock(&g_radar.lock);
  g_radar.callback = callback;
  g_radar.callback_arg = arg;
  pthread_mutex_unlock(&g_radar.lock);
}

int radar_get_latest(FAR struct radar_result_s *result)
{
  if (result == NULL)
    {
      return -EINVAL;
    }

  pthread_mutex_lock(&g_radar.lock);

  if (g_radar.latest.timestamp == 0)
    {
      pthread_mutex_unlock(&g_radar.lock);
      return -EAGAIN;
    }

  *result = g_radar.latest;
  pthread_mutex_unlock(&g_radar.lock);

  return 0;
}

bool radar_is_present(void)
{
  bool present;

  pthread_mutex_lock(&g_radar.lock);
  present = (g_radar.latest.state != RADAR_STATE_NO_TARGET);
  pthread_mutex_unlock(&g_radar.lock);

  return present;
}

uint8_t radar_get_zone_status(void)
{
  uint8_t zones;

  pthread_mutex_lock(&g_radar.lock);
  zones = g_radar.latest.zone;
  pthread_mutex_unlock(&g_radar.lock);

  return zones;
}

