 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <pthread.h>
#include <debug.h>
#include <errno.h>
#include <time.h>
#include <sys/ioctl.h>
#include <nuttx/ioexpander/gpio.h>

#include "smart_lock_config.h"
#include "door_sensor.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define TAG "door_sensor"

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct door_sensor_s
{
  int fd;                             /* GPIO file descriptor */
  volatile bool running;              /* Monitor task running */
  pthread_t monitor_tid;              /* Monitor task thread */
  door_event_callback_t callback;     /* Event callback */
  FAR void *callback_arg;             /* Callback argument */
  struct door_status_s status;        /* Current door status */
  pthread_mutex_t lock;               /* Data protection */
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct door_sensor_s g_door;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: door_sensor_read_gpio
 *
 * Description:
 *   Read the current state of the door sensor GPIO pin.
 *
 * Returned Value:
 *   true if door is closed (magnet aligned), false if open.
 *
 ****************************************************************************/

static bool door_sensor_read_gpio(void)
{
  bool value;
  int ret;

  if (g_door.fd < 0)
    {
      return false;
    }

  /* Read GPIO value */

  ret = ioctl(g_door.fd, GPIOC_READ, (unsigned long)&value);
  if (ret < 0)
    {
      syslog(LOG_ERR, TAG": GPIO read failed: %d\n", errno);
      return false;
    }

  /* Apply polarity (active low for reed switch) */

#if DOOR_SENSOR_ACTIVE_LOW
  return !value;  /* Invert: LOW = closed */
#else
  return value;   /* HIGH = closed */
#endif
}

/****************************************************************************
 * Name: door_sensor_monitor_task
 *
 * Description:
 *   Background task that monitors door sensor state changes using
 *   GPIO interrupt notification.
 *
 ****************************************************************************/

static FAR void *door_sensor_monitor_task(FAR void *arg)
{
  bool current_closed;
  bool previous_closed;
  struct timespec ts;

  syslog(LOG_INFO, TAG": Monitor task started\n");

  /* Read initial state */

  previous_closed = door_sensor_read_gpio();

  pthread_mutex_lock(&g_door.lock);
  g_door.status.door_state = previous_closed ?
                             DOOR_STATE_CLOSED : DOOR_STATE_OPEN;
  g_door.status.lock_state = LOCK_STATE_UNLOCKED;
  pthread_mutex_unlock(&g_door.lock);

  syslog(LOG_INFO, TAG": Initial state: %s\n",
         previous_closed ? "CLOSED" : "OPEN");

  while (g_door.running)
    {
      /* Read current state */

      current_closed = door_sensor_read_gpio();

      /* Check for state change */

      if (current_closed != previous_closed)
        {
          clock_gettime(CLOCK_MONOTONIC, &ts);
          uint32_t timestamp = (uint32_t)(ts.tv_sec * 1000 +
                                          ts.tv_nsec / 1000000);

          pthread_mutex_lock(&g_door.lock);

          if (current_closed)
            {
              /* Door just closed */

              g_door.status.door_state = DOOR_STATE_CLOSED;
              g_door.status.last_event = DOOR_EVENT_CLOSED;
              g_door.status.last_event_time = timestamp;

              syslog(LOG_INFO, TAG": Door CLOSED\n");
            }
          else
            {
              /* Door just opened */

              g_door.status.door_state = DOOR_STATE_OPEN;
              g_door.status.door_open_time = timestamp;
              g_door.status.last_event = DOOR_EVENT_OPENED;
              g_door.status.last_event_time = timestamp;
              g_door.status.lock_state = LOCK_STATE_UNLOCKED;

              syslog(LOG_INFO, TAG": Door OPENED\n");
            }

          /* Notify callback */

          if (g_door.callback != NULL)
            {
              struct door_status_s status = g_door.status;
              pthread_mutex_unlock(&g_door.lock);
              g_door.callback(&status, g_door.callback_arg);
              pthread_mutex_lock(&g_door.lock);
            }
          else
            {
              pthread_mutex_unlock(&g_door.lock);
            }

          previous_closed = current_closed;
        }

      /* Poll interval - 50ms for responsive detection */

      usleep(50000);
    }

  syslog(LOG_INFO, TAG": Monitor task exiting\n");
  return NULL;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int door_sensor_init(void)
{
  pthread_attr_t attr;
  char gpio_path[32];
  int ret;

  syslog(LOG_INFO, TAG": Initializing door sensor\n");

  /* Initialize context */

  memset(&g_door, 0, sizeof(g_door));
  g_door.fd = -1;
  g_door.running = false;
  pthread_mutex_init(&g_door.lock, NULL);

  /* Open GPIO device */

  snprintf(gpio_path, sizeof(gpio_path), "/dev/gpio%d",
           DOOR_SENSOR_GPIO_PIN);

  g_door.fd = open(gpio_path, O_RDONLY);
  if (g_door.fd < 0)
    {
      syslog(LOG_ERR, TAG": Failed to open %s: %d\n",
             gpio_path, errno);
      return -errno;
    }

  /* Configure as input */

  ret = ioctl(g_door.fd, GPIOC_SETPINCONFIG,
              (unsigned long)GPIO_INPUT_PULLUP);
  if (ret < 0)
    {
      syslog(LOG_WARNING, TAG": SetPinConfig failed: %d (may not be "
             "supported)\n", errno);
    }

  /* Start monitor task */

  g_door.running = true;

  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, 2048);
  pthread_attr_setschedpolicy(&attr, SCHED_RR);

  ret = pthread_create(&g_door.monitor_tid, &attr,
                       door_sensor_monitor_task, NULL);
  if (ret != 0)
    {
      syslog(LOG_ERR, TAG": Failed to create task: %d\n", ret);
      g_door.running = false;
      goto err_close;
    }

  syslog(LOG_INFO, TAG": Door sensor initialized on %s\n", gpio_path);
  return 0;

err_close:
  close(g_door.fd);
  g_door.fd = -1;
  pthread_mutex_destroy(&g_door.lock);
  return ret;
}

void door_sensor_deinit(void)
{
  syslog(LOG_INFO, TAG": Deinitializing door sensor\n");

  g_door.running = false;
  if (g_door.monitor_tid != 0)
    {
      pthread_join(g_door.monitor_tid, NULL);
    }

  if (g_door.fd >= 0)
    {
      close(g_door.fd);
      g_door.fd = -1;
    }

  pthread_mutex_destroy(&g_door.lock);
}

void door_sensor_register_callback(door_event_callback_t callback,
                                   FAR void *arg)
{
  pthread_mutex_lock(&g_door.lock);
  g_door.callback = callback;
  g_door.callback_arg = arg;
  pthread_mutex_unlock(&g_door.lock);
}

bool door_sensor_is_closed(void)
{
  bool closed;

  pthread_mutex_lock(&g_door.lock);
  closed = (g_door.status.door_state == DOOR_STATE_CLOSED);
  pthread_mutex_unlock(&g_door.lock);

  return closed;
}

int door_sensor_get_status(FAR struct door_status_s *status)
{
  if (status == NULL)
    {
      return -EINVAL;
    }

  pthread_mutex_lock(&g_door.lock);
  *status = g_door.status;
  pthread_mutex_unlock(&g_door.lock);

  return 0;
}

void door_sensor_set_lock(bool locked)
{
  pthread_mutex_lock(&g_door.lock);
  g_door.status.lock_state = locked ?
                             LOCK_STATE_LOCKED : LOCK_STATE_UNLOCKED;
  pthread_mutex_unlock(&g_door.lock);
}

