/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define TAG "door_ctrl"

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct door_ctrl_s
{
  int motor_open_fd;              /* GPIO fd for motor open */
  int motor_close_fd;             /* GPIO fd for motor close */
  int motor_lock_fd;              /* GPIO fd for motor lock */
  int buzzer_fd;                  /* GPIO fd for buzzer */
  int pwm_fd;                     /* PWM fd for motor speed control */

  volatile uint8_t motor_state;   /* Current motor state */
  uint32_t motor_start_time;      /* When motor started */
  uint8_t last_cmd;               /* Last command */
  pthread_mutex_t lock;           /* Data protection */
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct door_ctrl_s g_ctrl;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: get_timestamp_ms
 ****************************************************************************/

static uint32_t get_timestamp_ms(void)
{
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (uint32_t)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);
}

/****************************************************************************
 * Name: motor_gpio_write
 *
 * Description:
 *   Write a value to a motor GPIO pin.
 *
 ****************************************************************************/

static int motor_gpio_write(int fd, bool value)
{
  int ret;

  if (fd < 0)
    {
      return -EBADF;
    }

  ret = ioctl(fd, GPIOC_WRITE, (unsigned long)(value ? 1 : 0));
  if (ret < 0)
    {
      syslog(LOG_ERR, TAG": GPIO write failed: %d\n", errno);
    }

  return ret;
}

/****************************************************************************
 * Name: motor_stop_all
 *
 * Description:
 *   Stop all motor outputs.
 *
 ****************************************************************************/

static void motor_stop_all(void)
{
  motor_gpio_write(g_ctrl.motor_open_fd, false);
  motor_gpio_write(g_ctrl.motor_close_fd, false);
  motor_gpio_write(g_ctrl.motor_lock_fd, false);
}

/****************************************************************************
 * Name: open_gpio
 *
 * Description:
 *   Open and configure a GPIO pin.
 *
 ****************************************************************************/

static int open_gpio(int pin, int mode)
{
  char path[32];
  int fd;
  int ret;

  snprintf(path, sizeof(path), "/dev/gpio%d", pin);

  fd = open(path, O_RDWR);
  if (fd < 0)
    {
      syslog(LOG_ERR, TAG": Failed to open %s: %d\n", path, errno);
      return -errno;
    }

  /* Configure as output */

  ret = ioctl(fd, GPIOC_SETPINCONFIG, (unsigned long)mode);
  if (ret < 0)
    {
      syslog(LOG_WARNING, TAG": SetPinConfig on %s failed: %d\n",
             path, errno);
    }

  /* Set initial value to LOW */

  motor_gpio_write(fd, false);

  return fd;
}

/****************************************************************************
 * Name: buzzer_control
 *
 * Description:
 *   Control the buzzer (on/off).
 *
 ****************************************************************************/

static void buzzer_control(bool on)
{
  motor_gpio_write(g_ctrl.buzzer_fd, on);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int door_control_init(void)
{
  int ret;

  syslog(LOG_INFO, TAG": Initializing door control\n");

  /* Initialize context */

  memset(&g_ctrl, 0, sizeof(g_ctrl));
  g_ctrl.motor_open_fd = -1;
  g_ctrl.motor_close_fd = -1;
  g_ctrl.motor_lock_fd = -1;
  g_ctrl.buzzer_fd = -1;
  g_ctrl.pwm_fd = -1;
  g_ctrl.motor_state = MOTOR_STATE_IDLE;
  pthread_mutex_init(&g_ctrl.lock, NULL);

  /* Open motor control GPIOs */

  g_ctrl.motor_open_fd = open_gpio(MOTOR_OPEN_GPIO_PIN,
                                   GPIO_OUTPUT);
  if (g_ctrl.motor_open_fd < 0)
    {
      syslog(LOG_ERR, TAG": Failed to open motor open GPIO\n");
      ret = g_ctrl.motor_open_fd;
      goto err;
    }

  g_ctrl.motor_close_fd = open_gpio(MOTOR_CLOSE_GPIO_PIN,
                                    GPIO_OUTPUT);
  if (g_ctrl.motor_close_fd < 0)
    {
      syslog(LOG_ERR, TAG": Failed to open motor close GPIO\n");
      ret = g_ctrl.motor_close_fd;
      goto err;
    }

  g_ctrl.motor_lock_fd = open_gpio(MOTOR_LOCK_GPIO_PIN,
                                   GPIO_OUTPUT);
  if (g_ctrl.motor_lock_fd < 0)
    {
      syslog(LOG_ERR, TAG": Failed to open motor lock GPIO\n");
      ret = g_ctrl.motor_lock_fd;
      goto err;
    }

  /* Open buzzer GPIO */

  g_ctrl.buzzer_fd = open_gpio(BUZZER_GPIO_PIN, GPIO_OUTPUT);
  if (g_ctrl.buzzer_fd < 0)
    {
      syslog(LOG_WARNING, TAG": Failed to open buzzer GPIO: %d\n",
             g_ctrl.buzzer_fd);
      /* Non-fatal - buzzer is optional */
    }

  /* Open PWM for motor speed control (optional) */

  g_ctrl.pwm_fd = open("/dev/pwm0", O_RDONLY);
  if (g_ctrl.pwm_fd < 0)
    {
      syslog(LOG_WARNING, TAG": PWM not available, using GPIO only\n");
      /* Non-fatal - GPIO control works without PWM */
    }

  syslog(LOG_INFO, TAG": Door control initialized\n");
  return 0;

err:
  door_control_deinit();
  return ret;
}

void door_control_deinit(void)
{
  syslog(LOG_INFO, TAG": Deinitializing door control\n");

  /* Stop motor first */

  motor_stop_all();

  /* Close all file descriptors */

  if (g_ctrl.motor_open_fd >= 0)
    {
      close(g_ctrl.motor_open_fd);
      g_ctrl.motor_open_fd = -1;
    }

  if (g_ctrl.motor_close_fd >= 0)
    {
      close(g_ctrl.motor_close_fd);
      g_ctrl.motor_close_fd = -1;
    }

  if (g_ctrl.motor_lock_fd >= 0)
    {
      close(g_ctrl.motor_lock_fd);
      g_ctrl.motor_lock_fd = -1;
    }

  if (g_ctrl.buzzer_fd >= 0)
    {
      close(g_ctrl.buzzer_fd);
      g_ctrl.buzzer_fd = -1;
    }

  if (g_ctrl.pwm_fd >= 0)
    {
      close(g_ctrl.pwm_fd);
      g_ctrl.pwm_fd = -1;
    }

  pthread_mutex_destroy(&g_ctrl.lock);
}

int door_control_execute(uint8_t cmd)
{
  pthread_mutex_lock(&g_ctrl.lock);

  /* Check if motor is already running */

  if (g_ctrl.motor_state != MOTOR_STATE_IDLE &&
      cmd != MOTOR_CMD_EMERGENCY_STOP)
    {
      pthread_mutex_unlock(&g_ctrl.lock);
      syslog(LOG_WARNING, TAG": Motor busy (state=%d)\n",
             g_ctrl.motor_state);
      return -EBUSY;
    }

  /* Stop any current operation first */

  motor_stop_all();

  /* Execute command */

  switch (cmd)
    {
      case MOTOR_CMD_CLOSE:
        syslog(LOG_INFO, TAG": Closing door\n");
        motor_gpio_write(g_ctrl.motor_close_fd, true);
        g_ctrl.motor_state = MOTOR_STATE_CLOSING;
        break;

      case MOTOR_CMD_OPEN:
        syslog(LOG_INFO, TAG": Opening door\n");
        motor_gpio_write(g_ctrl.motor_open_fd, true);
        g_ctrl.motor_state = MOTOR_STATE_OPENING;
        break;

      case MOTOR_CMD_LOCK:
        syslog(LOG_INFO, TAG": Locking door\n");
        motor_gpio_write(g_ctrl.motor_lock_fd, true);
        g_ctrl.motor_state = MOTOR_STATE_LOCKING;
        break;

      case MOTOR_CMD_UNLOCK:
        syslog(LOG_INFO, TAG": Unlocking door\n");
        motor_gpio_write(g_ctrl.motor_lock_fd, false);
        g_ctrl.motor_state = MOTOR_STATE_IDLE;
        break;

      case MOTOR_CMD_EMERGENCY_STOP:
        syslog(LOG_WARNING, TAG": EMERGENCY STOP\n");
        motor_stop_all();
        buzzer_control(true);
        g_ctrl.motor_state = MOTOR_STATE_IDLE;
        pthread_mutex_unlock(&g_ctrl.lock);
        return 0;

      case MOTOR_CMD_STOP:
        motor_stop_all();
        g_ctrl.motor_state = MOTOR_STATE_IDLE;
        pthread_mutex_unlock(&g_ctrl.lock);
        return 0;

      default:
        syslog(LOG_ERR, TAG": Unknown command: %d\n", cmd);
        pthread_mutex_unlock(&g_ctrl.lock);
        return -EINVAL;
    }

  g_ctrl.last_cmd = cmd;
  g_ctrl.motor_start_time = get_timestamp_ms();

  pthread_mutex_unlock(&g_ctrl.lock);
  return 0;
}

void door_control_stop(void)
{
  pthread_mutex_lock(&g_ctrl.lock);
  motor_stop_all();
  buzzer_control(false);
  g_ctrl.motor_state = MOTOR_STATE_IDLE;
  pthread_mutex_unlock(&g_ctrl.lock);
}

void door_control_get_status(FAR struct motor_status_s *status)
{
  if (status == NULL)
    {
      return;
    }

  pthread_mutex_lock(&g_ctrl.lock);

  /* Check if motor should have finished by now */

  if (g_ctrl.motor_state != MOTOR_STATE_IDLE)
    {
      uint32_t elapsed = get_timestamp_ms() - g_ctrl.motor_start_time;
      uint32_t timeout;

      switch (g_ctrl.motor_state)
        {
          case MOTOR_STATE_CLOSING:
            timeout = DOOR_CLOSE_DURATION_MS;
            break;
          case MOTOR_STATE_LOCKING:
            timeout = DOOR_LOCK_DURATION_MS;
            break;
          default:
            timeout = SAFETY_TIMEOUT_MS;
            break;
        }

      if (elapsed >= timeout)
        {
          /* Motor operation complete */

          motor_stop_all();
          g_ctrl.motor_state = MOTOR_STATE_IDLE;
        }
    }

  status->state = g_ctrl.motor_state;
  status->start_time = g_ctrl.motor_start_time;
  status->last_cmd = g_ctrl.last_cmd;

  pthread_mutex_unlock(&g_ctrl.lock);
}

bool door_control_is_idle(void)
{
  bool idle;

  pthread_mutex_lock(&g_ctrl.lock);

  /* Check timeout */

  if (g_ctrl.motor_state != MOTOR_STATE_IDLE)
    {
      uint32_t elapsed = get_timestamp_ms() - g_ctrl.motor_start_time;
      if (elapsed >= SAFETY_TIMEOUT_MS)
        {
          motor_stop_all();
          g_ctrl.motor_state = MOTOR_STATE_IDLE;
        }
    }

  idle = (g_ctrl.motor_state == MOTOR_STATE_IDLE);
  pthread_mutex_unlock(&g_ctrl.lock);

  return idle;
}

