/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define TAG "safety"
#define ALARM_BUZZER_ON_MS    200     /* Buzzer beep duration */
#define ALARM_BUZZER_OFF_MS   200     /* Buzzer pause duration */
#define ALARM_PATTERN_COUNT   5       /* Number of beep cycles */

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct safety_ctx_s
{
  volatile bool running;              /* System running flag */
  volatile bool monitoring;           /* Anti-pinch monitoring active */
  volatile bool alarm_active;         /* Alarm currently sounding */
  pthread_t monitor_tid;              /* Monitor task thread */
  pthread_t alarm_tid;                /* Alarm task thread */
  safety_callback_t callback;         /* Alert callback */
  FAR void *callback_arg;             /* Callback argument */
  int buzzer_fd;                      /* Buzzer GPIO fd */
  pthread_mutex_t lock;               /* Data protection */
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct safety_ctx_s g_safety;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: buzzer_set
 *
 * Description:
 *   Control buzzer state.
 *
 ****************************************************************************/

static void buzzer_set(bool on)
{
  if (g_safety.buzzer_fd >= 0)
    {
      ioctl(g_safety.buzzer_fd, GPIOC_WRITE,
            (unsigned long)(on ? 1 : 0));
    }
}

/****************************************************************************
 * Name: notify_alert
 *
 * Description:
 *   Notify the registered callback about a safety alert.
 *
 ****************************************************************************/

static void notify_alert(uint8_t type, uint8_t severity,
                         FAR const char *message)
{
  struct safety_alert_s alert;

  memset(&alert, 0, sizeof(alert));
  alert.type = type;
  alert.severity = severity;

  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  alert.timestamp = (uint32_t)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);

  if (message != NULL)
    {
      strncpy(alert.message, message, sizeof(alert.message) - 1);
    }

  /* Notify callback */

  if (g_safety.callback != NULL)
    {
      g_safety.callback(&alert, g_safety.callback_arg);
    }
}

/****************************************************************************
 * Name: alarm_task
 *
 * Description:
 *   Task that controls buzzer alarm pattern.
 *
 ****************************************************************************/

static FAR void *alarm_task(FAR void *arg)
{
  uint8_t count = (uint8_t)(unsigned long)arg;

  syslog(LOG_INFO, TAG": Alarm task started (count=%d)\n", count);

  for (uint8_t i = 0; i < count && g_safety.alarm_active; i++)
    {
      buzzer_set(true);
      usleep(ALARM_BUZZER_ON_MS * 1000);

      buzzer_set(false);
      usleep(ALARM_BUZZER_OFF_MS * 1000);
    }

  buzzer_set(false);
  g_safety.alarm_active = false;

  syslog(LOG_INFO, TAG": Alarm task finished\n");
  return NULL;
}

/****************************************************************************
 * Name: start_alarm
 *
 * Description:
 *   Start the buzzer alarm with a specific pattern.
 *
 ****************************************************************************/

static void start_alarm(uint8_t pattern_count)
{
  pthread_attr_t attr;
  int ret;

  /* Stop any existing alarm */

  g_safety.alarm_active = false;
  usleep(10000);  /* Let old task finish */

  /* Start new alarm */

  g_safety.alarm_active = true;

  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, 1024);

  ret = pthread_create(&g_safety.alarm_tid, &attr,
                       alarm_task,
                       (FAR void *)(unsigned long)pattern_count);
  if (ret != 0)
    {
      syslog(LOG_ERR, TAG": Failed to create alarm task: %d\n", ret);
      g_safety.alarm_active = false;
    }
}

/****************************************************************************
 * Name: anti_pinch_monitor_task
 *
 * Description:
 *   High-priority task that monitors radar data during door closing
 *   to detect potential pinch situations. Runs at 20ms intervals.
 *
 ****************************************************************************/

static FAR void *anti_pinch_monitor_task(FAR void *arg)
{
  struct sched_param param;
  bool person_detected;
  uint32_t consecutive_detections = 0;

  syslog(LOG_INFO, TAG": Anti-pinch monitor started\n");

  /* Set high priority for real-time response */

  param.sched_priority = PRIO_SAFETY;
  pthread_setschedparam(pthread_self(), SCHED_RR, &param);

  while (g_safety.running)
    {
      /* Wait for monitoring to be activated */

      while (!g_safety.monitoring && g_safety.running)
        {
          usleep(50000);  /* 50ms idle polling */
          continue;
        }

      if (!g_safety.running)
        {
          break;
        }

      /* Active monitoring - check radar every 20ms */

      person_detected = radar_is_present();

      if (person_detected)
        {
          consecutive_detections++;

          /* Require multiple consecutive detections to avoid false
           * positives. 3 detections × 20ms = 60ms confirmation.
           */

          if (consecutive_detections >= 3)
            {
              syslog(LOG_WARNING,
                     TAG": ANTI-PINCH! Person detected during close\n");

              /* Trigger emergency stop */

              door_control_execute(MOTOR_CMD_EMERGENCY_STOP);

              /* Notify safety alert */

              notify_alert(SAFETY_ALERT_ANTI_PINCH,
                          SAFETY_SEVERITY_CRITICAL,
                          "Anti-pinch: person detected during door close");

              /* Start alarm */

              start_alarm(ALARM_PATTERN_COUNT);

              /* Reset counter */

              consecutive_detections = 0;

              /* Wait for monitoring to be re-activated */

              g_safety.monitoring = false;
            }
        }
      else
        {
          /* No detection - reset counter */

          consecutive_detections = 0;
        }

      /* 20ms check interval */

      usleep(ANTI_PINCH_CHECK_MS * 1000);
    }

  syslog(LOG_INFO, TAG": Anti-pinch monitor exited\n");
  return NULL;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int safety_init(void)
{
  pthread_attr_t attr;
  int ret;

  syslog(LOG_INFO, TAG": Initializing safety system\n");

  /* Initialize context */

  memset(&g_safety, 0, sizeof(g_safety));
  g_safety.running = false;
  g_safety.monitoring = false;
  g_safety.alarm_active = false;
  g_safety.buzzer_fd = -1;
  pthread_mutex_init(&g_safety.lock, NULL);

  /* Open buzzer GPIO */

  g_safety.buzzer_fd = open("/dev/gpio" BUZZER_GPIO_PIN_STR,
                            O_WRONLY);
  if (g_safety.buzzer_fd < 0)
    {
      syslog(LOG_WARNING, TAG": Buzzer GPIO not available: %d\n", errno);
      /* Non-fatal - safety monitoring still works without buzzer */
    }

  /* Start anti-pinch monitor task */

  g_safety.running = true;

  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, STACK_SAFETY);
  pthread_attr_setschedpolicy(&attr, SCHED_RR);
  param.sched_priority = PRIO_SAFETY;
  pthread_attr_setschedparam(&attr, &param);

  ret = pthread_create(&g_safety.monitor_tid, &attr,
                       anti_pinch_monitor_task, NULL);
  if (ret != 0)
    {
      syslog(LOG_ERR, TAG": Failed to create monitor task: %d\n", ret);
      g_safety.running = false;
      goto err;
