}

void safety_deinit(void)
{
  syslog(LOG_INFO, TAG": Deinitializing safety system\n");

  /* Stop all activities */

  g_safety.running = false;
  g_safety.monitoring = false;
  g_safety.alarm_active = false;

  /* Wait for tasks to finish */

  if (g_safety.monitor_tid != 0)
