{
  lv_obj_t *scr = lv_obj_create(NULL);
  g_ui.alert_screen = scr;

  /* Semi-transparent background */

  lv_obj_set_style_bg_color(scr, lv_color_hex(0x000000), 0);
  lv_obj_set_style_bg_opa(scr, LV_OPA_70, 0);

  /* Alert container */

  g_ui.alert_container = lv_obj_create(scr);
  lv_obj_set_size(g_ui.alert_container, SCREEN_WIDTH - 40, 120);
  lv_obj_align(g_ui.alert_container, LV_ALIGN_CENTER, 0, 0);
