/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <pthread.h>
#include <debug.h>
#include <errno.h>
#include <syslog.h>
#include <time.h>
#include <sys/ioctl.h>
#include <nuttx/power/pm.h>
#include <nuttx/timers/rtc.h>

#include "power_mgmt.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define TAG "power"
#define INACTIVITY_TIMEOUT_SEC 300  /* 5 minutes to enter idle */
#define SLEEP_TIMEOUT_SEC 600       /* 10 minutes to enter sleep */
#define BATTERY_CHECK_INTERVAL 60   /* Check battery every 60s */

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct power_ctx_s
{
  volatile bool initialized;
  volatile uint8_t mode;
  volatile uint32_t activity_time;
  volatile uint32_t wake_sources;
  pthread_t monitor_tid;
  volatile bool running;
  pthread_mutex_t lock;

  /* Battery simulation */

  volatile uint8_t battery_level;
  volatile bool charging;
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct power_ctx_s g_power;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: get_timestamp_sec
 ****************************************************************************/

static uint32_t get_timestamp_sec(void)
{
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (uint32_t)ts.tv_sec;
}

/****************************************************************************
 * Name: pm_prepare_sleep
 *
 * Description:
 *   Callback from PM framework before entering sleep.
 *
 ****************************************************************************/

static int pm_prepare_sleep(uint8_t domain, int state)
{
  syslog(LOG_INFO, TAG": Preparing for sleep: domain=%d state=%d\n",
         domain, state);

  /* Check if any wake source is active */

  if (g_power.wake_sources == 0)
    {
      syslog(LOG_WARNING, TAG": No wake sources configured!\n");
    }

  return OK;
}

/****************************************************************************
 * Name: pm_sleep_notify
 *
 * Description:
 *   Callback from PM framework after waking up.
 *
 ****************************************************************************/

static void pm_sleep_notify(uint8_t domain, int state)
{
  syslog(LOG_INFO, TAG": Woke up: domain=%d state=%d\n", domain, state);

  /* Reset activity timer */

  g_power.activity_time = get_timestamp_sec();
}

/* PM callbacks */

static struct pm_activity_s g_pm_activity =
{
  .prepare = pm_prepare_sleep,
  .notify  = pm_sleep_notify,
};

/****************************************************************************
 * Name: power_monitor_task
 *
 * Description:
 *   Background task that monitors power state and manages transitions.
 *
 ****************************************************************************/

static FAR void *power_monitor_task(FAR void *arg)
{
  uint32_t now;
  uint32_t inactive_time;

  syslog(LOG_INFO, TAG": Power monitor task started\n");

  while (g_power.running)
    {
      now = get_timestamp_sec();
      inactive_time = now - g_power.activity_time;

      /* Check for mode transitions */

      switch (g_power.mode)
        {
          case POWER_MODE_ACTIVE:
            if (inactive_time > INACTIVITY_TIMEOUT_SEC)
              {
                syslog(LOG_INFO, TAG": Inactive %ds, entering idle\n",
                       inactive_time);
                power_mgmt_set_mode(POWER_MODE_IDLE);
              }
            break;

          case POWER_MODE_IDLE:
            if (inactive_time > SLEEP_TIMEOUT_SEC)
              {
                syslog(LOG_INFO, TAG": Inactive %ds, entering sleep\n",
                       inactive_time);
                power_mgmt_set_mode(POWER_MODE_SLEEP);
              }
            break;

          case POWER_MODE_SLEEP:
            /* In sleep mode, just wait for wake interrupt */

            break;

          case POWER_MODE_STANDBY:
            /* In standby, everything is off except wake sources */

            break;
        }

      /* Check battery level periodically */

      static uint32_t last_battery_check = 0;
      if (now - last_battery_check > BATTERY_CHECK_INTERVAL)
        {
          /* TODO: Read actual battery ADC value */

          /* Simulate battery drain */

          if (!g_power.charging && g_power.battery_level > 0)
            {
              g_power.battery_level--;
            }
          else if (g_power.charging && g_power.battery_level < 100)
            {
              g_power.battery_level++;
            }

          last_battery_check = now;
        }

      /* Sleep for 1 second */

      sleep(1);
    }

  syslog(LOG_INFO, TAG": Power monitor task exited\n");
  return NULL;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int power_mgmt_init(void)
{
  pthread_attr_t attr;
  int ret;

  syslog(LOG_INFO, TAG": Initializing power management\n");

  /* Initialize context */

  memset(&g_power, 0, sizeof(g_power));
  g_power.initialized = false;
  g_power.mode = POWER_MODE_ACTIVE;
  g_power.activity_time = get_timestamp_sec();
  g_power.wake_sources = WAKE_SRC_RADAR | WAKE_SRC_DOOR_SENSOR |
                         WAKE_SRC_BUTTON;
  g_power.battery_level = 100;
  g_power.charging = false;
  pthread_mutex_init(&g_power.lock, NULL);

  /* Register PM callbacks */

  ret = pm_activity_register(&g_pm_activity);
  if (ret < 0)
    {
      syslog(LOG_WARNING, TAG": PM register failed: %d\n", ret);
      /* Non-fatal - PM will work without callbacks */
    }

  /* Start monitor task */

  g_power.running = true;

  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, 2048);

  ret = pthread_create(&g_power.monitor_tid, &attr,
                       power_monitor_task, NULL);
  if (ret != 0)
    {
      syslog(LOG_ERR, TAG": Failed to create monitor task: %d\n", ret);
      g_power.running = false;
      goto err;
    }

  g_power.initialized = true;

  syslog(LOG_INFO, TAG": Power management initialized\n");
  return 0;

err:
  pthread_mutex_destroy(&g_power.lock);
  return ret;
}

void power_mgmt_deinit(void)
{
  syslog(LOG_INFO, TAG": Deinitializing power management\n");

  g_power.running = false;
  if (g_power.monitor_tid != 0)
    {
      pthread_join(g_power.monitor_tid, NULL);
    }

  g_power.initialized = false;
  pthread_mutex_destroy(&g_power.lock);
}

int power_mgmt_set_mode(uint8_t mode)
{
  if (!g_power.initialized)
    {
      return -ENODEV;
    }

  if (mode > POWER_MODE_STANDBY)
    {
      return -EINVAL;
    }

  pthread_mutex_lock(&g_power.lock);

  if (g_power.mode != mode)
    {
      syslog(LOG_INFO, TAG": Mode %d -> %d\n", g_power.mode, mode);
      g_power.mode = mode;

      /* Apply power mode changes */

      switch (mode)
        {
          case POWER_MODE_ACTIVE:
            /* Full power - wake all peripherals */

            pm_activity(PM_IDLE_DOMAIN, 0);
            break;

          case POWER_MODE_IDLE:
            /* Reduce CPU clock, keep BLE + radar */

            pm_activity(PM_IDLE_DOMAIN, 1);
            break;

          case POWER_MODE_SLEEP:
            /* Deep sleep - BLE only */

            pm_activity(PM_IDLE_DOMAIN, 2);
            break;

          case POWER_MODE_STANDBY:
            /* Standby - minimal power */

            pm_activity(PM_IDLE_DOMAIN, 3);
            break;
        }
    }

  pthread_mutex_unlock(&g_power.lock);
  return 0;
}

uint8_t power_mgmt_get_mode(void)
{
  return g_power.mode;
}

void power_mgmt_get_status(FAR struct power_status_s *status)
{
  if (status == NULL)
    {
      return;
    }

  pthread_mutex_lock(&g_power.lock);
  status->mode = g_power.mode;
  status->battery_level = g_power.battery_level;
  status->charging = g_power.charging;
  status->uptime_sec = get_timestamp_sec();
  status->wake_sources = g_power.wake_sources;
  pthread_mutex_unlock(&g_power.lock);
}

uint8_t power_mgmt_get_battery_level(void)
{
  return g_power.battery_level;
}

bool power_mgmt_is_charging(void)
{
  return g_power.charging;
}

void power_mgmt_enable_wake_source(uint32_t source)
{
  pthread_mutex_lock(&g_power.lock);
  g_power.wake_sources |= source;
  pthread_mutex_unlock(&g_power.lock);

  syslog(LOG_DEBUG, TAG": Wake sources: 0x%08x\n", g_power.wake_sources);
}

void power_mgmt_disable_wake_source(uint32_t source)
{
  pthread_mutex_lock(&g_power.lock);
  g_power.wake_sources &= ~source;
  pthread_mutex_unlock(&g_power.lock);

  syslog(LOG_DEBUG, TAG": Wake sources: 0x%08x\n", g_power.wake_sources);
}

void power_mgmt_enter_sleep(void)
{
  if (!g_power.initialized)
    {
      return;
    }

  syslog(LOG_INFO, TAG": Entering sleep mode\n");

  /* Set sleep mode */

  power_mgmt_set_mode(POWER_MODE_SLEEP);

  /* The actual sleep is handled by the PM framework */

  /* Configure RTC alarm to wake up */

  struct rtc_setalarm_s alarm;
  struct timespec ts;

  clock_gettime(CLOCK_REALTIME, &ts);
  ts.tv_sec += 60;  /* Wake in 60 seconds */

  alarm.id = 0;
  alarm.pid = getpid();
  alarm.event.sigev_notify = SIGEV_SIGNAL;
  alarm.event.sigev_signo = SIGALRM;
  alarm.event.sigev_value.sival_int = 0;
  alarm.time = ts;

  /* TODO: Set RTC alarm */

  /* Enter idle loop - PM framework will handle sleep */

  while (g_power.mode == POWER_MODE_SLEEP)
    {
      sleep(1);
    }
}

void power_mgmt_activity_reset(void)
{
  g_power.activity_time = get_timestamp_sec();

  /* If in low power mode, wake up */

  if (g_power.mode != POWER_MODE_ACTIVE)
    {
      power_mgmt_set_mode(POWER_MODE_ACTIVE);
    }
}

uint32_t power_mgmt_get_uptime(void)
{
  return get_timestamp_sec();
}

