#### 4.3 优化播放逻辑

```c
// voice_alert.c - 添加语音队列

#define VOICE_QUEUE_SIZE 5

static uint8_t voice_queue[VOICE_QUEUE_SIZE];
static uint8_t queue_head = 0;
static uint8_t queue_tail = 0;

int voice_alert_enqueue(uint8_t voice_id, uint8_t priority)
{
    // 检查队列是否满
    uint8_t next = (queue_tail + 1) % VOICE_QUEUE_SIZE;
    if (next == queue_head)
    {
        return -ENOSPC;
    }

    // 高优先级插入队首
    if (priority >= VOICE_PRIORITY_HIGH)
    {
        queue_head = (queue_head - 1 + VOICE_QUEUE_SIZE) % VOICE_QUEUE_SIZE;
        voice_queue[queue_head] = voice_id;
    }
    else
    {
        voice_queue[queue_tail] = voice_id;
        queue_tail = next;
    }

    return 0;
}
```

