    async initBLE() {
      try {
        await ble.init();
        await ble.startScan();
        ble.onDeviceFound = this.onDeviceFound.bind(this);
      } catch (e) {
        console.error('BLE init failed:', e);
      }
    },

    onDeviceFound(device) {
      if (device.name === 'SmartLock') {
        ble.connect(device.deviceId);
        this.bleStatus = '已连接';
        this.connected = true;
      }
    },

    async openDoor() {
      if (!this.connected) return;
      await ble.write([0x01]);  // CMD_OPEN
    },

    async closeDoor() {
      if (!this.connected) return;
      await ble.write([0x02]);  // CMD_CLOSE
    },

    async lockDoor() {
      if (!this.connected) return;
      await ble.write([0x03]);  // CMD_LOCK
    },

    goToSettings() {
      router.push('/settings');
    },

    onDestroy() {
      ble.disconnect();
    }
  }
</script>
