```javascript
// ble.js - BLE通信模块

class BLEManager {
  constructor() {
    this.deviceId = null;
    this.serviceId = '00001820-0000-1000-8000-00805f9b34fb';
    this.characteristicId = '00002b21-0000-1000-8000-00805f9b34fb';
    this.notifyCharacteristicId = '00002b23-0000-1000-8000-00805f9b34fb';
    this.onDeviceFound = null;
    this.onDataReceived = null;
  }

  init() {
    return new Promise((resolve, reject) => {
      ble.initialize({
        success: () => resolve(),
        fail: (err) => reject(err)
      });
    });
  }

  startScan() {
    return new Promise((resolve, reject) => {
      ble.startScan({
        services: [this.serviceId],
        success: (devices) => {
          devices.forEach(device => {
            if (this.onDeviceFound) {
              this.onDeviceFound(device);
            }
          });
          resolve();
        },
        fail: (err) => reject(err)
      });
    });
  }

  connect(deviceId) {
    return new Promise((resolve, reject) => {
      this.deviceId = deviceId;
      ble.connect({
        deviceId: deviceId,
        success: () => {
          this.subscribe();
          resolve();
        },
        fail: (err) => reject(err)
      });
    });
  }

  disconnect() {
    if (this.deviceId) {
      ble.closeBLEConnection({
        deviceId: this.deviceId,
        success: () => {
          this.deviceId = null;
        }
      });
    }
  }

  subscribe() {
    ble.notifyBLECharacteristicValueChange({
      deviceId: this.deviceId,
      serviceId: this.serviceId,
      characteristicId: this.notifyCharacteristicId,
      state: true,
      success: () => {
        ble.onBLECharacteristicValueChange = (res) => {
          if (this.onDataReceived) {
            this.onDataReceived(new Uint8Array(res.value));
          }
        };
      }
    });
  }

  write(data) {
    return new Promise((resolve, reject) => {
      ble.writeBLECharacteristicValue({
        deviceId: this.deviceId,
        serviceId: this.serviceId,
        characteristicId: this.characteristicId,
        value: new Uint8Array(data).buffer,
        success: () => resolve(),
        fail: (err) => reject(err)
      });
    });
  }
}

export default new BLEManager();
