{
  struct radar_result_s radar;
  struct door_status_s door;
  struct motor_status_s motor;
  bool radar_ok;
  bool door_ok;

  radar_ok = (radar_get_latest(&radar) == 0);
  door_ok = (door_sensor_get_status(&door) == 0);
  door_control_get_status(&motor);

  printf("{\n");
  printf("  \"radar\": {\n");
