210	                                 uint16_t offset, uint8_t flags)
211	{
212	    if (len < 1)
213	    {
214	        return BT_GATT_ERR(BT_ATT_ERR_INVALID_ATTRIBUTE_LEN);
215	    }
216	
217	    uint8_t cmd = ((const uint8_t *)buf)[0];
